def solve(case):
    payload = case.get("payload") or case  # handle both structures

    segments = payload["segments"]
    budget = payload["budget"]

    # Validate required fields
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError("segments must be a non-empty list")
    if not isinstance(budget, int) or budget < 0:
        raise ValueError("budget must be a non-negative integer")

    for i, seg in enumerate(segments):
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in seg:
                raise ValueError(f"Segment {i} missing field '{field}'")
        if seg["minimum"] < 0:
            raise ValueError(f"Segment {seg['name']} has negative minimum")
        if seg["capacity"] < seg["minimum"]:
            raise ValueError(f"Segment {seg['name']} capacity < minimum")
        if seg["importance"] < 0:
            raise ValueError(f"Segment {seg['name']} has negative importance")

    quota_sum = sum(seg["minimum"] for seg in segments)
    capacity_sum = sum(seg["capacity"] for seg in segments)

    if budget < quota_sum:
        raise ValueError(f"Budget {budget} < quota sum {quota_sum}")
    if budget > capacity_sum:
        raise ValueError(f"Budget {budget} > capacity sum {capacity_sum}")

    # Initialize at minimum
    allocations = [seg["minimum"] for seg in segments]
    remaining = budget - quota_sum

    # Greedy allocation
    while remaining > 0:
        best_idx = -1
        best_priority = None

        for i, seg in enumerate(segments):
            if allocations[i] >= seg["capacity"]:
                continue  # at capacity, skip

            next_pos = allocations[i] + 1
            priority = seg["importance"] / next_pos

            if best_idx == -1 or priority > best_priority:
                best_priority = priority
                best_idx = i

        if best_idx == -1:
            raise ValueError("Cannot allocate remaining budget: all segments at capacity")

        allocations[best_idx] += 1
        remaining -= 1

    # Build result
    total = sum(allocations)

    allocation_list = [
        {"name": seg["name"], "allocated": allocations[i]}
        for i, seg in enumerate(segments)
    ]

    name_map = {
        seg["name"]: {
            "importance": seg["importance"],
            "minimum": seg["minimum"],
            "capacity": seg["capacity"],
            "allocated": allocations[i]
        }
        for i, seg in enumerate(segments)
    }

    return {
        "allocations": allocation_list,
        "name_map": name_map,
        "total": total
    }
```

